class Customer extends DataClass implements Insertable<Customer> {
  final int id;
  final String name;
  final String phone;
  final String? address;
  final double totalDue;
  final double creditLimit;
  final int creditDays;
  final double unclearCheque;
  final bool isRetailCustomer;
  final bool isWholesaleCustomer;
  final bool isActive;
  final String createdAt;
  final String updatedAt;
  const Customer(
      {required this.id,
      required this.name,
      required this.phone,
      this.address,
      required this.totalDue,
      required this.creditLimit,
      required this.creditDays,
      required this.unclearCheque,
      required this.isRetailCustomer,
      required this.isWholesaleCustomer,
      required this.isActive,
      required this.createdAt,
      required this.updatedAt});
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['name'] = Variable<String>(name);
    map['phone'] = Variable<String>(phone);
    if (!nullToAbsent || address != null) {
      map['address'] = Variable<String>(address);
    }
    map['total_due'] = Variable<double>(totalDue);
    map['credit_limit'] = Variable<double>(creditLimit);
    map['credit_days'] = Variable<int>(creditDays);
    map['unclear_cheque'] = Variable<double>(unclearCheque);
    map['is_retail_customer'] = Variable<bool>(isRetailCustomer);
    map['is_wholesale_customer'] = Variable<bool>(isWholesaleCustomer);
    map['is_active'] = Variable<bool>(isActive);
    map['created_at'] = Variable<String>(createdAt);
    map['updated_at'] = Variable<String>(updatedAt);
    return map;
  }

  CustomersCompanion toCompanion(bool nullToAbsent) {
    return CustomersCompanion(
      id: Value(id),
      name: Value(name),
      phone: Value(phone),
      address: address == null && nullToAbsent
          ? const Value.absent()
          : Value(address),
      totalDue: Value(totalDue),
      creditLimit: Value(creditLimit),
      creditDays: Value(creditDays),
      unclearCheque: Value(unclearCheque),
      isRetailCustomer: Value(isRetailCustomer),
      isWholesaleCustomer: Value(isWholesaleCustomer),
      isActive: Value(isActive),
      createdAt: Value(createdAt),
      updatedAt: Value(updatedAt),
    );
  }

  factory Customer.fromJson(Map<String, dynamic> json,
      {ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return Customer(
      id: serializer.fromJson<int>(json['id']),
      name: serializer.fromJson<String>(json['name']),
      phone: serializer.fromJson<String>(json['phone']),
      address: serializer.fromJson<String?>(json['address']),
      totalDue: serializer.fromJson<double>(json['totalDue']),
      creditLimit: serializer.fromJson<double>(json['creditLimit']),
      creditDays: serializer.fromJson<int>(json['creditDays']),
      unclearCheque: serializer.fromJson<double>(json['unclearCheque']),
      isRetailCustomer: serializer.fromJson<bool>(json['isRetailCustomer']),
      isWholesaleCustomer:
          serializer.fromJson<bool>(json['isWholesaleCustomer']),
      isActive: serializer.fromJson<bool>(json['isActive']),
      createdAt: serializer.fromJson<String>(json['createdAt']),
      updatedAt: serializer.fromJson<String>(json['updatedAt']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<int>(id),
      'name': serializer.toJson<String>(name),
      'phone': serializer.toJson<String>(phone),
      'address': serializer.toJson<String?>(address),
      'totalDue': serializer.toJson<double>(totalDue),
      'creditLimit': serializer.toJson<double>(creditLimit),
      'creditDays': serializer.toJson<int>(creditDays),
      'unclearCheque': serializer.toJson<double>(unclearCheque),
      'isRetailCustomer': serializer.toJson<bool>(isRetailCustomer),
      'isWholesaleCustomer': serializer.toJson<bool>(isWholesaleCustomer),
      'isActive': serializer.toJson<bool>(isActive),
      'createdAt': serializer.toJson<String>(createdAt),
      'updatedAt': serializer.toJson<String>(updatedAt),
    };
  }

  Customer copyWith(
          {int? id,
          String? name,
          String? phone,
          Value<String?> address = const Value.absent(),
          double? totalDue,
          double? creditLimit,
          int? creditDays,
          double? unclearCheque,
          bool? isRetailCustomer,
          bool? isWholesaleCustomer,
          bool? isActive,
          String? createdAt,
          String? updatedAt}) =>
      Customer(
        id: id ?? this.id,
        name: name ?? this.name,
        phone: phone ?? this.phone,
        address: address.present ? address.value : this.address,
        totalDue: totalDue ?? this.totalDue,
        creditLimit: creditLimit ?? this.creditLimit,
        creditDays: creditDays ?? this.creditDays,
        unclearCheque: unclearCheque ?? this.unclearCheque,
        isRetailCustomer: isRetailCustomer ?? this.isRetailCustomer,
        isWholesaleCustomer: isWholesaleCustomer ?? this.isWholesaleCustomer,
        isActive: isActive ?? this.isActive,
        createdAt: createdAt ?? this.createdAt,
        updatedAt: updatedAt ?? this.updatedAt,
