  Customer copyWithCompanion(CustomersCompanion data) {
    return Customer(
      id: data.id.present ? data.id.value : this.id,
      name: data.name.present ? data.name.value : this.name,
      phone: data.phone.present ? data.phone.value : this.phone,
      address: data.address.present ? data.address.value : this.address,
      totalDue: data.totalDue.present ? data.totalDue.value : this.totalDue,
      creditLimit:
          data.creditLimit.present ? data.creditLimit.value : this.creditLimit,
      creditDays:
          data.creditDays.present ? data.creditDays.value : this.creditDays,
      unclearCheque: data.unclearCheque.present
          ? data.unclearCheque.value
          : this.unclearCheque,
      isRetailCustomer: data.isRetailCustomer.present
          ? data.isRetailCustomer.value
          : this.isRetailCustomer,
      isWholesaleCustomer: data.isWholesaleCustomer.present
          ? data.isWholesaleCustomer.value
          : this.isWholesaleCustomer,
      isActive: data.isActive.present ? data.isActive.value : this.isActive,
      createdAt: data.createdAt.present ? data.createdAt.value : this.createdAt,
      updatedAt: data.updatedAt.present ? data.updatedAt.value : this.updatedAt,
    );
  }

  @override
  String toString() {
    return (StringBuffer('Customer(')
          ..write('id: $id, ')
          ..write('name: $name, ')
          ..write('phone: $phone, ')
          ..write('address: $address, ')
          ..write('totalDue: $totalDue, ')
          ..write('creditLimit: $creditLimit, ')
          ..write('creditDays: $creditDays, ')
          ..write('unclearCheque: $unclearCheque, ')
          ..write('isRetailCustomer: $isRetailCustomer, ')
          ..write('isWholesaleCustomer: $isWholesaleCustomer, ')
          ..write('isActive: $isActive, ')
          ..write('createdAt: $createdAt, ')
          ..write('updatedAt: $updatedAt')
          ..write(')'))
        .toString();
  }

  @override
  int get hashCode => Object.hash(
      id,
      name,
      phone,
      address,
      totalDue,
      creditLimit,
      creditDays,
      unclearCheque,
      isRetailCustomer,
      isWholesaleCustomer,
      isActive,
      createdAt,
      updatedAt);
  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      (other is Customer &&
          other.id == this.id &&
          other.name == this.name &&
          other.phone == this.phone &&
          other.address == this.address &&
          other.totalDue == this.totalDue &&
          other.creditLimit == this.creditLimit &&
          other.creditDays == this.creditDays &&
          other.unclearCheque == this.unclearCheque &&
          other.isRetailCustomer == this.isRetailCustomer &&
          other.isWholesaleCustomer == this.isWholesaleCustomer &&
