    if (!nullToAbsent || username != null) {
      map['username'] = Variable<String>(username);
    }
    if (!nullToAbsent || email != null) {
      map['email'] = Variable<String>(email);
    }
    map['phone'] = Variable<String>(phone);
    if (!nullToAbsent || address != null) {
      map['address'] = Variable<String>(address);
    }
    map['role'] = Variable<String>(role);
    map['employee_id'] = Variable<String>(employeeId);
    if (!nullToAbsent || salary != null) {
      map['salary'] = Variable<double>(salary);
    }
    map['hire_date'] = Variable<String>(hireDate);
    if (!nullToAbsent || terminationDate != null) {
      map['termination_date'] = Variable<String>(terminationDate);
    }
    map['is_active'] = Variable<bool>(isActive);
    map['can_login'] = Variable<bool>(canLogin);
    if (!nullToAbsent || password != null) {
      map['password'] = Variable<String>(password);
    }
    if (!nullToAbsent || permissions != null) {
      map['permissions'] = Variable<String>(permissions);
    }
    if (!nullToAbsent || commissionPercentage != null) {
      map['commission_percentage'] = Variable<double>(commissionPercentage);
    }
    map['created_at'] = Variable<String>(createdAt);
    map['updated_at'] = Variable<String>(updatedAt);
    return map;
  }

  EmployeesCompanion toCompanion(bool nullToAbsent) {
    return EmployeesCompanion(
      id: Value(id),
      name: Value(name),
      username: username == null && nullToAbsent
          ? const Value.absent()
          : Value(username),
      email:
          email == null && nullToAbsent ? const Value.absent() : Value(email),
      phone: Value(phone),
      address: address == null && nullToAbsent
          ? const Value.absent()
          : Value(address),
      role: Value(role),
